### Objective
Build a production-grade Deep Link Ingress Manager in Flutter. Demonstrate both Cold-Start and Warm-State link handling, deferred navigation queueing that waits for asynchronous application bootstrap, parameter extraction with defensive validation, and seamless declarative route dispatch.

```dart
import 'dart:async';
import 'package:flutter/material.dart';

void main() async {
  WidgetsFlutterBinding.ensureInitialized();

  // 1. Initialize DeepLinkService and simulate background bootstrap
  final deepLinkService = DeepLinkService();
  await deepLinkService.initializeBootstrap();

  runApp(DeepLinkApp(deepLinkService: deepLinkService));
}

// ─────────────────────────────────────────────────────────────────────────────
// 1. DEEP LINK INGRESS SERVICE WITH DEFERRED BOOTSTRAP QUEUE
// ─────────────────────────────────────────────────────────────────────────────

class DeepLinkPayload {
  final Uri uri;
  final String path;
  final Map<String, String> queryParameters;

  const DeepLinkPayload({
    required this.uri,
    required this.path,
    required this.queryParameters,
  });
}

class DeepLinkService {
  final _linkStreamController = StreamController<DeepLinkPayload>.broadcast();
  Stream<DeepLinkPayload> get linkStream => _linkStreamController.stream;

  bool _isBootstrapComplete = false;
  DeepLinkPayload? _pendingColdStartLink;

  /// Simulates asynchronous app bootstrap (loading Hive, reading secure tokens)
  Future<void> initializeBootstrap() async {
    debugPrint('🚀 [BOOTSTRAP] Initializing database, DI, and authentication...');

    // Simulate cold-start link arrival during boot
    _simulateInitialColdStartLink();

    // Simulate 1.2 second async initialization delay
    await Future.delayed(const Duration(milliseconds: 1200));
    _isBootstrapComplete = true;

    debugPrint('✅ [BOOTSTRAP COMPLETE] System ready. Processing deferred links...');

    // If a cold start link was held, dispatch it now!
    if (_pendingColdStartLink != null) {
      _dispatchLink(_pendingColdStartLink!);
      _pendingColdStartLink = null;
    }
  }

  void _simulateInitialColdStartLink() {
    // Simulates OS handing an initial URI: https://app.example.com/promo/summer2026?discount=20
    final initialUri = Uri.parse('https://app.example.com/promo/summer2026?discount=20');
    _pendingColdStartLink = DeepLinkPayload(
      uri: initialUri,
      path: initialUri.path,
      queryParameters: initialUri.queryParameters,
    );
  }

  /// Called whenever a new link arrives (either cold start or warm stream)
  void handleIncomingUri(Uri uri) {
    debugPrint('🌐 [INGRESS LINK DETECTED] -> $uri');

    final payload = DeepLinkPayload(
      uri: uri,
      path: uri.path,
      queryParameters: uri.queryParameters,
    );

    if (!_isBootstrapComplete) {
      debugPrint('⏳ [DEFERRED] App still bootstrapping. Holding link in queue...');
      _pendingColdStartLink = payload;
      return;
    }

    _dispatchLink(payload);
  }

  void _dispatchLink(DeepLinkPayload payload) {
    // Defensive parameter sanitization
    debugPrint('🎯 [DISPATCHING TO ROUTER] Path: ${payload.path}, Params: ${payload.queryParameters}');
    _linkStreamController.add(payload);
  }

  void dispose() {
    _linkStreamController.close();
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 2. PRESENTATION LAYER
// ─────────────────────────────────────────────────────────────────────────────

class DeepLinkApp extends StatefulWidget {
  final DeepLinkService deepLinkService;
  const DeepLinkApp({super.key, required this.deepLinkService});

  @override
  State<DeepLinkApp> createState() => _DeepLinkAppState();
}

class _DeepLinkAppState extends State<DeepLinkApp> {
  final GlobalKey<NavigatorState> _navigatorKey = GlobalKey<NavigatorState>();
  late final StreamSubscription<DeepLinkPayload> _linkSubscription;

  @override
  void initState() {
    super.initState();
    // Listen to sanitized deep link payloads and route dynamically
    _linkSubscription = widget.deepLinkService.linkStream.listen((payload) {
      _handleDeepLinkNavigation(payload);
    });
  }

  void _handleDeepLinkNavigation(DeepLinkPayload payload) {
    final context = _navigatorKey.currentContext;
    if (context == null) return;

    if (payload.path.startsWith('/promo/')) {
      final promoCode = payload.path.replaceFirst('/promo/', '');
      final discount = payload.queryParameters['discount'] ?? '0';

      Navigator.of(context).push(
        MaterialPageRoute(
          builder: (_) => PromoOfferScreen(
            promoCode: promoCode,
            discountPercent: discount,
          ),
        ),
      );
    } else if (payload.path.startsWith('/product/')) {
      final productId = payload.path.replaceFirst('/product/', '');
      Navigator.of(context).push(
        MaterialPageRoute(
          builder: (_) => ProductViewScreen(productId: productId),
        ),
      );
    }
  }

  @override
  void dispose() {
    _linkSubscription.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      navigatorKey: _navigatorKey,
      title: 'Deep Linking Architecture',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        colorSchemeSeed: Colors.blueAccent,
        useMaterial3: true,
      ),
      home: DeepLinkHomeScreen(deepLinkService: widget.deepLinkService),
    );
  }
}

class DeepLinkHomeScreen extends StatelessWidget {
  final DeepLinkService deepLinkService;
  const DeepLinkHomeScreen({super.key, required this.deepLinkService});

  void _simulateExternalLink(String url) {
    deepLinkService.handleIncomingUri(Uri.parse(url));
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Deep Link Ingress Hub'),
        centerTitle: true,
      ),
      body: ListView(
        padding: const EdgeInsets.all(20),
        children: [
          _buildInfoBanner(),
          const SizedBox(height: 20),
          const Text('Simulate Ingress Links (Warm State)', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 16)),
          const SizedBox(height: 12),
          _buildSimulateButton(
            title: 'Simulate Promo Campaign Link',
            url: 'https://app.example.com/promo/flutter2026?discount=50',
            icon: Icons.local_offer_rounded,
            color: Colors.green,
            onTap: () => _simulateExternalLink('https://app.example.com/promo/flutter2026?discount=50'),
          ),
          const SizedBox(height: 12),
          _buildSimulateButton(
            title: 'Simulate Product Deep Link',
            url: 'https://app.example.com/product/macbook_m3_pro',
            icon: Icons.shopping_bag_rounded,
            color: Colors.blue,
            onTap: () => _simulateExternalLink('https://app.example.com/product/macbook_m3_pro'),
          ),
          const SizedBox(height: 24),
          _buildConfigCard(),
        ],
      ),
    );
  }

  Widget _buildInfoBanner() {
    return Card(
      elevation: 0,
      color: Colors.blue.shade50,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: const Padding(
        padding: EdgeInsets.all(16),
        child: Row(
          children: [
            Icon(Icons.link_rounded, color: Colors.blueAccent, size: 32),
            SizedBox(width: 14),
            Expanded(
              child: Text(
                'Demonstrates deferred cold-start queueing, Android App Links, iOS Universal Links, and defensive parameter routing.',
                style: TextStyle(fontSize: 12, height: 1.4, color: Colors.blueAccent, fontWeight: FontWeight.w600),
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildSimulateButton({
    required String title,
    required String url,
    required IconData icon,
    required Color color,
    required VoidCallback onTap,
  }) {
    return Card(
      elevation: 1,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: ListTile(
        leading: CircleAvatar(backgroundColor: color.withValues(alpha: 0.15), child: Icon(icon, color: color)),
        title: Text(title, style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 14)),
        subtitle: Text(url, style: const TextStyle(fontSize: 11, fontFamily: 'monospace', color: Colors.black54)),
        trailing: const Icon(Icons.arrow_forward_ios, size: 14),
        onTap: onTap,
      ),
    );
  }

  Widget _buildConfigCard() {
    return Card(
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: const Padding(
        padding: EdgeInsets.all(18),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text('Digital Asset Links & AASA Rules', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 15)),
            SizedBox(height: 10),
            Text(
              '• Android: Host assetlinks.json at /.well-known/assetlinks.json with package name & SHA-256 fingerprint.\n\n'
              '• iOS: Host apple-app-site-association with Team ID & Bundle ID without redirects.\n\n'
              '• Always queue incoming links until app dependencies and auth are fully initialized.',
              style: TextStyle(fontSize: 12, height: 1.5, color: Colors.black87),
            ),
          ],
        ),
      ),
    );
  }
}

